/*
 * hbx_ui.c - HBLauncher Native 2D renderer and geometry builder.
 *
 * Real Vulkan: one pipeline, one vertex buffer, one glyph atlas (R8), one icon
 * array (RGBA8), dynamic rendering, one draw per frame.  Every triangle is
 * generated by CPU code (rounded rectangles, strokes, circles, feathered
 * lines and glyph quads) -- nothing is a full-screen shader trick.
 *
 * The renderer is display-agnostic: `hbx_ui_attach_swapchain` wires the vi
 * swapchain for the console, `hbx_ui_render_offscreen` renders into an image
 * for the host preview and tests.
 *
 * Copyright (c) 2026 HBLauncher Native contributors.  MIT licensed.
 */
#include "hbx_ui_internal.h"
#include "hbx_ui_shaders.h"
#include "hbx_math.h"

/* ------------------------------------------------------------------ */
/* Small helpers                                                      */
/* ------------------------------------------------------------------ */

static VkResult device_memory_type(struct hbx_ui_impl *impl, uint32_t required,
                                   uint32_t bits, uint32_t *out) {
    VkPhysicalDeviceMemoryProperties properties;
    uint32_t i;
    if (!impl->d->vkGetPhysicalDeviceMemoryProperties) return VK_ERROR_FEATURE_NOT_PRESENT;
    hbx_memset(&properties, 0, sizeof properties);
    impl->d->vkGetPhysicalDeviceMemoryProperties(impl->physical, &properties);
    for (i = 0; i < properties.memoryTypeCount && i < 32u; i++) {
        if ((bits & (1u << i)) &&
            (properties.memoryTypes[i].propertyFlags & required) == required) {
            *out = i;
            return VK_SUCCESS;
        }
    }
    return VK_ERROR_FEATURE_NOT_PRESENT;
}

static VkResult create_image_2d(struct hbx_ui_impl *impl, VkFormat format,
                                uint32_t width, uint32_t height, uint32_t layers,
                                VkImage *image, VkDeviceMemory *memory) {
    VkImageCreateInfo info;
    VkMemoryRequirements requirements;
    VkMemoryAllocateInfo allocation;
    uint32_t type = 0;
    VkResult r;

    hbx_memset(&info, 0, sizeof info);
    info.sType = VK_STRUCTURE_TYPE_IMAGE_CREATE_INFO;
    info.imageType = VK_IMAGE_TYPE_2D;
    info.format = format;
    info.extent.width = width;
    info.extent.height = height;
    info.extent.depth = 1;
    info.mipLevels = 1;
    info.arrayLayers = layers;
    info.samples = VK_SAMPLE_COUNT_1_BIT;
    info.tiling = VK_IMAGE_TILING_OPTIMAL;
    info.usage = VK_IMAGE_USAGE_TRANSFER_DST_BIT | VK_IMAGE_USAGE_SAMPLED_BIT;
    info.sharingMode = VK_SHARING_MODE_EXCLUSIVE;
    info.initialLayout = VK_IMAGE_LAYOUT_UNDEFINED;
    r = impl->d->vkCreateImage(impl->device, &info, NULL, image);
    if (r != VK_SUCCESS) return r;

    hbx_memset(&requirements, 0, sizeof requirements);
    impl->d->vkGetImageMemoryRequirements(impl->device, *image, &requirements);
    r = device_memory_type(impl, VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT,
                           requirements.memoryTypeBits, &type);
    if (r != VK_SUCCESS) {
        impl->d->vkDestroyImage(impl->device, *image, NULL);
        *image = VK_NULL_HANDLE;
        return r;
    }
    hbx_memset(&allocation, 0, sizeof allocation);
    allocation.sType = VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO;
    allocation.allocationSize = requirements.size;
    allocation.memoryTypeIndex = type;
    r = impl->d->vkAllocateMemory(impl->device, &allocation, NULL, memory);
    if (r != VK_SUCCESS) {
        impl->d->vkDestroyImage(impl->device, *image, NULL);
        *image = VK_NULL_HANDLE;
        return r;
    }
    return impl->d->vkBindImageMemory(impl->device, *image, *memory, 0);
}

static VkResult create_view_2d(struct hbx_ui_impl *impl, VkImage image, VkFormat format,
                               uint32_t layers, VkImageViewType type, VkImageView *view) {
    VkImageViewCreateInfo info;
    hbx_memset(&info, 0, sizeof info);
    info.sType = VK_STRUCTURE_TYPE_IMAGE_VIEW_CREATE_INFO;
    info.image = image;
    info.viewType = type;
    info.format = format;
    info.subresourceRange.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;
    info.subresourceRange.baseMipLevel = 0;
    info.subresourceRange.levelCount = 1;
    info.subresourceRange.baseArrayLayer = 0;
    info.subresourceRange.layerCount = layers;
    return impl->d->vkCreateImageView(impl->device, &info, NULL, view);
}

static void transition_image(struct hbx_ui_impl *impl, VkCommandBuffer command,
                             VkImage image, VkImageLayout from, VkImageLayout to,
                             VkAccessFlags src_access, VkAccessFlags dst_access,
                             VkPipelineStageFlags src_stage, VkPipelineStageFlags dst_stage) {
    VkImageMemoryBarrier barrier;
    hbx_memset(&barrier, 0, sizeof barrier);
    barrier.sType = VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER;
    barrier.srcAccessMask = src_access;
    barrier.dstAccessMask = dst_access;
    barrier.oldLayout = from;
    barrier.newLayout = to;
    barrier.srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
    barrier.dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
    barrier.image = image;
    barrier.subresourceRange.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;
    barrier.subresourceRange.baseMipLevel = 0;
    barrier.subresourceRange.levelCount = 1;
    barrier.subresourceRange.baseArrayLayer = 0;
    barrier.subresourceRange.layerCount = VK_REMAINING_ARRAY_LAYERS;
    impl->d->vkCmdPipelineBarrier(command, src_stage, dst_stage, 0,
                                  0, NULL, 0, NULL, 1, &barrier);
}

/* Upload pixels into an image and leave it in SHADER_READ_ONLY_OPTIMAL.
 *
 * The transition covers the whole image (all array layers) from its *current*
 * layout, so a later partial upload preserves the layers it does not copy.
 * The shared upload command buffer is reset and reused, so uploads never
 * accumulate command buffers. */
static VkResult upload_image(struct hbx_ui_impl *impl, VkImage image, VkFormat format,
                             VkImageLayout *layout, uint32_t width, uint32_t height,
                             uint32_t image_layers, uint32_t copy_layers,
                             uint32_t layer_bytes, const void *pixels) {
    VkBufferCreateInfo buffer_info;
    VkMemoryRequirements requirements;
    VkMemoryAllocateInfo allocation;
    VkBufferImageCopy copies[HBX_MAX_ICON_LAYERS];
    VkCommandBufferBeginInfo begin;
    VkSubmitInfo submit;
    VkCommandBuffer command = impl->upload_command;
    void *mapped = NULL;
    VkBuffer staging = VK_NULL_HANDLE;
    VkDeviceMemory staging_memory = VK_NULL_HANDLE;
    uint32_t type = 0;
    uint32_t i;
    VkResult r;
    (void)format;

    if (copy_layers == 0 || copy_layers > image_layers || image_layers > HBX_MAX_ICON_LAYERS)
        return VK_ERROR_INITIALIZATION_FAILED;

    hbx_memset(&buffer_info, 0, sizeof buffer_info);
    buffer_info.sType = VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO;
    buffer_info.size = (VkDeviceSize)layer_bytes * copy_layers;
    buffer_info.usage = VK_BUFFER_USAGE_TRANSFER_SRC_BIT;
    buffer_info.sharingMode = VK_SHARING_MODE_EXCLUSIVE;
    r = impl->d->vkCreateBuffer(impl->device, &buffer_info, NULL, &staging);
    if (r != VK_SUCCESS) return r;
    hbx_memset(&requirements, 0, sizeof requirements);
    impl->d->vkGetBufferMemoryRequirements(impl->device, staging, &requirements);
    r = device_memory_type(impl, VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT |
                                   VK_MEMORY_PROPERTY_HOST_COHERENT_BIT,
                           requirements.memoryTypeBits, &type);
    if (r != VK_SUCCESS) return r;
    hbx_memset(&allocation, 0, sizeof allocation);
    allocation.sType = VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO;
    allocation.allocationSize = requirements.size;
    allocation.memoryTypeIndex = type;
    r = impl->d->vkAllocateMemory(impl->device, &allocation, NULL, &staging_memory);
    if (r != VK_SUCCESS) return r;
    r = impl->d->vkBindBufferMemory(impl->device, staging, staging_memory, 0);
    if (r != VK_SUCCESS) return r;
    r = impl->d->vkMapMemory(impl->device, staging_memory, 0, VK_WHOLE_SIZE, 0, &mapped);
    if (r != VK_SUCCESS || !mapped) {
        impl->d->vkFreeMemory(impl->device, staging_memory, NULL);
        impl->d->vkDestroyBuffer(impl->device, staging, NULL);
        return r != VK_SUCCESS ? r : VK_ERROR_MEMORY_MAP_FAILED;
    }
    if (pixels) hbx_memcpy(mapped, pixels, (size_t)layer_bytes * copy_layers);
    else hbx_memset(mapped, 0, (size_t)layer_bytes * copy_layers);
    impl->d->vkUnmapMemory(impl->device, staging_memory);

    if (impl->d->vkResetCommandBuffer) impl->d->vkResetCommandBuffer(command, 0);
    hbx_memset(&begin, 0, sizeof begin);
    begin.sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO;
    begin.flags = VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;
    r = impl->d->vkBeginCommandBuffer(command, &begin);
    if (r != VK_SUCCESS) {
        impl->d->vkFreeMemory(impl->device, staging_memory, NULL);
        impl->d->vkDestroyBuffer(impl->device, staging, NULL);
        return r;
    }

    {
        VkImageMemoryBarrier barrier;
        hbx_memset(&barrier, 0, sizeof barrier);
        barrier.sType = VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER;
        barrier.oldLayout = *layout;
        barrier.newLayout = VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL;
        barrier.srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
        barrier.dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
        barrier.image = image;
        barrier.subresourceRange.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;
        barrier.subresourceRange.levelCount = 1;
        barrier.subresourceRange.layerCount = image_layers;
        if (*layout == VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL) {
            barrier.srcAccessMask = VK_ACCESS_SHADER_READ_BIT;
            barrier.dstAccessMask = VK_ACCESS_TRANSFER_WRITE_BIT;
            impl->d->vkCmdPipelineBarrier(command, VK_PIPELINE_STAGE_FRAGMENT_SHADER_BIT,
                                          VK_PIPELINE_STAGE_TRANSFER_BIT, 0,
                                          0, NULL, 0, NULL, 1, &barrier);
        } else {
            barrier.dstAccessMask = VK_ACCESS_TRANSFER_WRITE_BIT;
            impl->d->vkCmdPipelineBarrier(command, VK_PIPELINE_STAGE_TOP_OF_PIPE_BIT,
                                          VK_PIPELINE_STAGE_TRANSFER_BIT, 0,
                                          0, NULL, 0, NULL, 1, &barrier);
        }
    }

    for (i = 0; i < copy_layers; i++) {
        hbx_memset(&copies[i], 0, sizeof copies[i]);
        copies[i].bufferOffset = (VkDeviceSize)layer_bytes * i;
        copies[i].imageSubresource.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;
        copies[i].imageSubresource.mipLevel = 0;
        copies[i].imageSubresource.baseArrayLayer = i;
        copies[i].imageSubresource.layerCount = 1;
        copies[i].imageExtent.width = width;
        copies[i].imageExtent.height = height;
        copies[i].imageExtent.depth = 1;
    }
    impl->d->vkCmdCopyBufferToImage(command, staging, image,
                                    VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL, copy_layers, copies);
    {
        VkImageMemoryBarrier barrier;
        hbx_memset(&barrier, 0, sizeof barrier);
        barrier.sType = VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER;
        barrier.oldLayout = VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL;
        barrier.newLayout = VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL;
        barrier.srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
        barrier.dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
        barrier.image = image;
        barrier.subresourceRange.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;
        barrier.subresourceRange.levelCount = 1;
        barrier.subresourceRange.layerCount = image_layers;
        barrier.srcAccessMask = VK_ACCESS_TRANSFER_WRITE_BIT;
        barrier.dstAccessMask = VK_ACCESS_SHADER_READ_BIT;
        impl->d->vkCmdPipelineBarrier(command, VK_PIPELINE_STAGE_TRANSFER_BIT,
                                      VK_PIPELINE_STAGE_FRAGMENT_SHADER_BIT, 0,
                                      0, NULL, 0, NULL, 1, &barrier);
    }
    r = impl->d->vkEndCommandBuffer(command);
    if (r == VK_SUCCESS) {
        hbx_memset(&submit, 0, sizeof submit);
        submit.sType = VK_STRUCTURE_TYPE_SUBMIT_INFO;
        submit.commandBufferCount = 1;
        submit.pCommandBuffers = &command;
        r = impl->d->vkQueueSubmit(impl->queue, 1, &submit, VK_NULL_HANDLE);
        if (r == VK_SUCCESS) r = impl->d->vkQueueWaitIdle(impl->queue);
    }
    if (r == VK_SUCCESS) *layout = VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL;

    impl->d->vkFreeMemory(impl->device, staging_memory, NULL);
    impl->d->vkDestroyBuffer(impl->device, staging, NULL);
    return r;
}

/* ------------------------------------------------------------------ */
/* Initialisation                                                     */
/* ------------------------------------------------------------------ */

static VkShaderModule create_module(struct hbx_ui_impl *impl, const uint32_t *words,
                                    uint32_t count) {
    VkShaderModuleCreateInfo info;
    VkShaderModule module = VK_NULL_HANDLE;
    hbx_memset(&info, 0, sizeof info);
    info.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
    info.codeSize = (size_t)count * 4u;
    info.pCode = words;
    if (impl->d->vkCreateShaderModule(impl->device, &info, NULL, &module) != VK_SUCCESS)
        return VK_NULL_HANDLE;
    return module;
}

static VkResult create_pipeline(struct hbx_ui_impl *impl) {
    VkDescriptorSetLayoutBinding bindings[3];
    VkDescriptorSetLayoutCreateInfo layout_info;
    VkDescriptorPoolSize pool_size;
    VkDescriptorPoolCreateInfo pool_info;
    VkDescriptorSetAllocateInfo set_info;
    VkDescriptorImageInfo atlas_info, icon_info, image_info;
    VkWriteDescriptorSet writes[3];
    VkSamplerCreateInfo sampler;
    VkPushConstantRange push;
    VkPipelineLayoutCreateInfo pipeline_layout_info;
    VkPipelineShaderStageCreateInfo stages[2];
    VkVertexInputBindingDescription binding;
    VkVertexInputAttributeDescription attributes[4];
    VkPipelineVertexInputStateCreateInfo vertex_input;
    VkPipelineInputAssemblyStateCreateInfo input_assembly;
    VkViewport viewport;
    VkRect2D scissor;
    VkPipelineViewportStateCreateInfo viewport_state;
    VkPipelineRasterizationStateCreateInfo raster;
    VkPipelineMultisampleStateCreateInfo multisample;
    VkPipelineColorBlendAttachmentState blend_attachment;
    VkPipelineColorBlendStateCreateInfo blend;
    VkPipelineRenderingCreateInfo rendering;
    VkGraphicsPipelineCreateInfo pipeline_info;
    VkResult r;
    uint32_t i;

    impl->vert_module = create_module(impl, hbx_shader_ui_vert, hbx_shader_ui_vert_words);
    impl->frag_module = create_module(impl, hbx_shader_ui_frag, hbx_shader_ui_frag_words);
    if (!impl->vert_module || !impl->frag_module) return VK_ERROR_INITIALIZATION_FAILED;

    for (i = 0; i < 3u; i++) {
        hbx_memset(&bindings[i], 0, sizeof bindings[i]);
        bindings[i].binding = i;
        bindings[i].descriptorType = VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER;
        bindings[i].descriptorCount = 1;
        bindings[i].stageFlags = VK_SHADER_STAGE_FRAGMENT_BIT;
    }
    hbx_memset(&layout_info, 0, sizeof layout_info);
    layout_info.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO;
    layout_info.bindingCount = 3;
    layout_info.pBindings = bindings;
    r = impl->d->vkCreateDescriptorSetLayout(impl->device, &layout_info, NULL, &impl->set_layout);
    if (r != VK_SUCCESS) return r;

    hbx_memset(&sampler, 0, sizeof sampler);
    sampler.sType = VK_STRUCTURE_TYPE_SAMPLER_CREATE_INFO;
    sampler.magFilter = VK_FILTER_NEAREST;
    sampler.minFilter = VK_FILTER_NEAREST;
    sampler.mipmapMode = VK_SAMPLER_MIPMAP_MODE_NEAREST;
    sampler.addressModeU = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;
    sampler.addressModeV = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;
    sampler.addressModeW = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;
    sampler.maxLod = 0.25f;
    r = impl->d->vkCreateSampler(impl->device, &sampler, NULL, &impl->atlas_sampler);
    if (r != VK_SUCCESS) return r;
    sampler.magFilter = VK_FILTER_LINEAR;
    sampler.minFilter = VK_FILTER_LINEAR;
    sampler.mipmapMode = VK_SAMPLER_MIPMAP_MODE_LINEAR;
    r = impl->d->vkCreateSampler(impl->device, &sampler, NULL, &impl->icon_sampler);
    if (r != VK_SUCCESS) return r;

    hbx_memset(&pool_size, 0, sizeof pool_size);
    pool_size.type = VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER;
    pool_size.descriptorCount = 3;
    hbx_memset(&pool_info, 0, sizeof pool_info);
    pool_info.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO;
    pool_info.maxSets = 1;
    pool_info.poolSizeCount = 1;
    pool_info.pPoolSizes = &pool_size;
    r = impl->d->vkCreateDescriptorPool(impl->device, &pool_info, NULL, &impl->descriptor_pool);
    if (r != VK_SUCCESS) return r;

    hbx_memset(&set_info, 0, sizeof set_info);
    set_info.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO;
    set_info.descriptorPool = impl->descriptor_pool;
    set_info.descriptorSetCount = 1;
    set_info.pSetLayouts = &impl->set_layout;
    r = impl->d->vkAllocateDescriptorSets(impl->device, &set_info, &impl->descriptor_set);
    if (r != VK_SUCCESS) return r;

    hbx_memset(&atlas_info, 0, sizeof atlas_info);
    atlas_info.sampler = impl->atlas_sampler;
    atlas_info.imageView = impl->atlas_view;
    atlas_info.imageLayout = VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL;
    hbx_memset(&icon_info, 0, sizeof icon_info);
    icon_info.sampler = impl->icon_sampler;
    icon_info.imageView = impl->icon_view;
    icon_info.imageLayout = VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL;

    hbx_memset(&image_info, 0, sizeof image_info);
    image_info.sampler = impl->app_sampler;
    image_info.imageView = impl->app_view;
    image_info.imageLayout = VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL;
    for (i = 0; i < 3u; i++) {
        hbx_memset(&writes[i], 0, sizeof writes[i]);
        writes[i].sType = VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET;
        writes[i].dstSet = impl->descriptor_set;
        writes[i].dstBinding = i;
        writes[i].descriptorCount = 1;
        writes[i].descriptorType = VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER;
        writes[i].pImageInfo = i == 0 ? &atlas_info : (i == 1 ? &icon_info : &image_info);
    }
    impl->d->vkUpdateDescriptorSets(impl->device, 3, writes, 0, NULL);

    hbx_memset(&push, 0, sizeof push);
    push.stageFlags = VK_SHADER_STAGE_VERTEX_BIT;
    push.offset = 0;
    push.size = 8; /* vec2 screen */
    hbx_memset(&pipeline_layout_info, 0, sizeof pipeline_layout_info);
    pipeline_layout_info.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
    pipeline_layout_info.setLayoutCount = 1;
    pipeline_layout_info.pSetLayouts = &impl->set_layout;
    pipeline_layout_info.pushConstantRangeCount = 1;
    pipeline_layout_info.pPushConstantRanges = &push;
    r = impl->d->vkCreatePipelineLayout(impl->device, &pipeline_layout_info, NULL,
                                        &impl->pipeline_layout);
    if (r != VK_SUCCESS) return r;

    hbx_memset(stages, 0, sizeof stages);
    stages[0].sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
    stages[0].stage = VK_SHADER_STAGE_VERTEX_BIT;
    stages[0].module = impl->vert_module;
    stages[0].pName = "main";
    stages[1].sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
    stages[1].stage = VK_SHADER_STAGE_FRAGMENT_BIT;
    stages[1].module = impl->frag_module;
    stages[1].pName = "main";

    hbx_memset(&binding, 0, sizeof binding);
    binding.binding = 0;
    binding.stride = HBX_UI_VERTEX_BYTES;
    binding.inputRate = VK_VERTEX_INPUT_RATE_VERTEX;
    hbx_memset(attributes, 0, sizeof attributes);
    attributes[0].location = 0;
    attributes[0].format = VK_FORMAT_R32G32_SFLOAT;
    attributes[0].offset = 0;
    attributes[1].location = 1;
    attributes[1].format = VK_FORMAT_R32G32_SFLOAT;
    attributes[1].offset = 8;
    attributes[2].location = 2;
    attributes[2].format = VK_FORMAT_R8G8B8A8_UNORM;
    attributes[2].offset = 16;
    attributes[3].location = 3;
    attributes[3].format = VK_FORMAT_R32_UINT;
    attributes[3].offset = 20;
    for (i = 0; i < 4u; i++) attributes[i].binding = 0;

    hbx_memset(&vertex_input, 0, sizeof vertex_input);
    vertex_input.sType = VK_STRUCTURE_TYPE_PIPELINE_VERTEX_INPUT_STATE_CREATE_INFO;
    vertex_input.vertexBindingDescriptionCount = 1;
    vertex_input.pVertexBindingDescriptions = &binding;
    vertex_input.vertexAttributeDescriptionCount = 4;
    vertex_input.pVertexAttributeDescriptions = attributes;

    hbx_memset(&input_assembly, 0, sizeof input_assembly);
    input_assembly.sType = VK_STRUCTURE_TYPE_PIPELINE_INPUT_ASSEMBLY_STATE_CREATE_INFO;
    input_assembly.topology = VK_PRIMITIVE_TOPOLOGY_TRIANGLE_LIST;

    hbx_memset(&viewport, 0, sizeof viewport);
    viewport.width = (float)impl->width;
    viewport.height = (float)impl->height;
    viewport.maxDepth = 1.0f;
    hbx_memset(&scissor, 0, sizeof scissor);
    scissor.extent.width = impl->width;
    scissor.extent.height = impl->height;
    hbx_memset(&viewport_state, 0, sizeof viewport_state);
    viewport_state.sType = VK_STRUCTURE_TYPE_PIPELINE_VIEWPORT_STATE_CREATE_INFO;
    viewport_state.viewportCount = 1;
    viewport_state.pViewports = &viewport;
    viewport_state.scissorCount = 1;
    viewport_state.pScissors = &scissor;

    hbx_memset(&raster, 0, sizeof raster);
    raster.sType = VK_STRUCTURE_TYPE_PIPELINE_RASTERIZATION_STATE_CREATE_INFO;
    raster.polygonMode = VK_POLYGON_MODE_FILL;
    raster.cullMode = VK_CULL_MODE_NONE;
    raster.frontFace = VK_FRONT_FACE_COUNTER_CLOCKWISE;
    raster.lineWidth = 1.0f;

    hbx_memset(&multisample, 0, sizeof multisample);
    multisample.sType = VK_STRUCTURE_TYPE_PIPELINE_MULTISAMPLE_STATE_CREATE_INFO;
    multisample.rasterizationSamples = VK_SAMPLE_COUNT_1_BIT;

    hbx_memset(&blend_attachment, 0, sizeof blend_attachment);
    blend_attachment.blendEnable = VK_TRUE;
    blend_attachment.srcColorBlendFactor = VK_BLEND_FACTOR_SRC_ALPHA;
    blend_attachment.dstColorBlendFactor = VK_BLEND_FACTOR_ONE_MINUS_SRC_ALPHA;
    blend_attachment.colorBlendOp = VK_BLEND_OP_ADD;
    blend_attachment.srcAlphaBlendFactor = VK_BLEND_FACTOR_SRC_ALPHA;
    blend_attachment.dstAlphaBlendFactor = VK_BLEND_FACTOR_ONE_MINUS_SRC_ALPHA;
    blend_attachment.alphaBlendOp = VK_BLEND_OP_ADD;
    blend_attachment.colorWriteMask = VK_COLOR_COMPONENT_R_BIT | VK_COLOR_COMPONENT_G_BIT |
                                      VK_COLOR_COMPONENT_B_BIT | VK_COLOR_COMPONENT_A_BIT;
    hbx_memset(&blend, 0, sizeof blend);
    blend.sType = VK_STRUCTURE_TYPE_PIPELINE_COLOR_BLEND_STATE_CREATE_INFO;
    blend.attachmentCount = 1;
    blend.pAttachments = &blend_attachment;

    hbx_memset(&rendering, 0, sizeof rendering);
    rendering.sType = VK_STRUCTURE_TYPE_PIPELINE_RENDERING_CREATE_INFO;
    rendering.colorAttachmentCount = 1;
    rendering.pColorAttachmentFormats = &impl->format;

    hbx_memset(&pipeline_info, 0, sizeof pipeline_info);
    pipeline_info.sType = VK_STRUCTURE_TYPE_GRAPHICS_PIPELINE_CREATE_INFO;
    pipeline_info.pNext = &rendering;
    pipeline_info.stageCount = 2;
    pipeline_info.pStages = stages;
    pipeline_info.pVertexInputState = &vertex_input;
    pipeline_info.pInputAssemblyState = &input_assembly;
    pipeline_info.pViewportState = &viewport_state;
    pipeline_info.pRasterizationState = &raster;
    pipeline_info.pMultisampleState = &multisample;
    pipeline_info.pColorBlendState = &blend;
    pipeline_info.layout = impl->pipeline_layout;
    r = impl->d->vkCreateGraphicsPipelines(impl->device, VK_NULL_HANDLE, 1, &pipeline_info,
                                           NULL, &impl->pipeline);
    if (r != VK_SUCCESS) return r;
    return VK_SUCCESS;
}

VkResult hbx_ui_init(struct hbx_ui_impl *impl, const struct hbx_vk_dispatch *d,
                     VkInstance instance, VkPhysicalDevice physical,
                     VkDevice device, VkQueue queue, uint32_t queue_family,
                     uint32_t width, uint32_t height, VkFormat format,
                     const void *atlas_pixels, uint32_t atlas_bytes,
                     uint32_t icon_layers) {
    VkCommandPoolCreateInfo pool_info;
    VkBufferCreateInfo buffer_info;
    VkMemoryRequirements requirements;
    VkMemoryAllocateInfo allocation;
    uint32_t type = 0;
    VkResult r;

    if (!impl || !d) return VK_ERROR_INITIALIZATION_FAILED;
    if (!atlas_pixels || atlas_bytes < HBX_ATLAS_SIZE * HBX_ATLAS_SIZE)
        return VK_ERROR_INITIALIZATION_FAILED;
    hbx_memset(impl, 0, sizeof *impl);
    impl->abi = HBX_RENDER_ABI;
    impl->d = d;
    impl->instance = instance;
    impl->physical = physical;
    impl->device = device;
    impl->queue = queue;
    impl->queue_family = queue_family;
    impl->width = width ? width : 1920;
    impl->height = height ? height : 1080;
    impl->format = format ? format : VK_FORMAT_R8G8B8A8_UNORM;
    /* The icon array is always sized for the maximum number of titles so a
     * growing catalog never needs the image recreated. */
    (void)icon_layers;
    impl->icon_layers = HBX_MAX_ICON_LAYERS;
    impl->atlas_layout = VK_IMAGE_LAYOUT_UNDEFINED;
    impl->icon_layout = VK_IMAGE_LAYOUT_UNDEFINED;

    hbx_memset(&pool_info, 0, sizeof pool_info);
    pool_info.sType = VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO;
    pool_info.flags = VK_COMMAND_POOL_CREATE_RESET_COMMAND_BUFFER_BIT;
    pool_info.queueFamilyIndex = queue_family;
    r = d->vkCreateCommandPool(device, &pool_info, NULL, &impl->command_pool);
    if (r != VK_SUCCESS) return r;

    /* All command buffers (one per swapchain image plus the shared upload
     * buffer) are allocated up front: texture uploads run during init. */
    {
        VkCommandBufferAllocateInfo info;
        uint32_t i;
        hbx_memset(&info, 0, sizeof info);
        info.sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO;
        info.commandPool = impl->command_pool;
        info.level = VK_COMMAND_BUFFER_LEVEL_PRIMARY;
        info.commandBufferCount = HBX_MAX_IMAGES + 1;
        r = d->vkAllocateCommandBuffers(device, &info, impl->commands);
        if (r != VK_SUCCESS) return r;
        impl->upload_command = impl->commands[HBX_MAX_IMAGES];
        for (i = 0; i < HBX_MAX_IMAGES; i++) impl->images[i] = VK_NULL_HANDLE;
    }

    /* Glyph atlas */
    r = create_image_2d(impl, VK_FORMAT_R8_UNORM, HBX_ATLAS_SIZE, HBX_ATLAS_SIZE, 1,
                        &impl->atlas_image, &impl->atlas_memory);
    if (r != VK_SUCCESS) return r;
    r = create_view_2d(impl, impl->atlas_image, VK_FORMAT_R8_UNORM, 1,
                       VK_IMAGE_VIEW_TYPE_2D, &impl->atlas_view);
    if (r != VK_SUCCESS) return r;
    if (!atlas_pixels || atlas_bytes < HBX_ATLAS_SIZE * HBX_ATLAS_SIZE)
        return VK_ERROR_INITIALIZATION_FAILED;
    r = upload_image(impl, impl->atlas_image, VK_FORMAT_R8_UNORM, &impl->atlas_layout,
                     HBX_ATLAS_SIZE, HBX_ATLAS_SIZE, 1, 1,
                     HBX_ATLAS_SIZE * HBX_ATLAS_SIZE, atlas_pixels);
    if (r != VK_SUCCESS) return r;

    /* Icon array */
    r = create_image_2d(impl, VK_FORMAT_R8G8B8A8_UNORM, HBX_ICON_SIZE, HBX_ICON_SIZE,
                        impl->icon_layers, &impl->icon_image, &impl->icon_memory);
    if (r != VK_SUCCESS) return r;
    r = create_view_2d(impl, impl->icon_image, VK_FORMAT_R8G8B8A8_UNORM, impl->icon_layers,
                       VK_IMAGE_VIEW_TYPE_2D_ARRAY, &impl->icon_view);
    if (r != VK_SUCCESS) return r;
    /* Zero every layer so an unreferenced icon samples as transparent. */
    r = upload_image(impl, impl->icon_image, VK_FORMAT_R8G8B8A8_UNORM,
                     &impl->icon_layout, HBX_ICON_SIZE, HBX_ICON_SIZE,
                     impl->icon_layers, impl->icon_layers,
                     HBX_ICON_SIZE * HBX_ICON_SIZE * 4u, NULL);
    if (r != VK_SUCCESS) return r;

    /* App image: a 512x512 RGBA texture uploaded on demand by hbx_ui image. */
    r = create_image_2d(impl, VK_FORMAT_R8G8B8A8_UNORM, 512, 512, 1,
                        &impl->app_image, &impl->app_memory);
    if (r != VK_SUCCESS) return r;
    r = create_view_2d(impl, impl->app_image, VK_FORMAT_R8G8B8A8_UNORM, 1,
                       VK_IMAGE_VIEW_TYPE_2D, &impl->app_view);
    if (r != VK_SUCCESS) return r;
    {
        VkSamplerCreateInfo sampler;
        hbx_memset(&sampler, 0, sizeof sampler);
        sampler.sType = VK_STRUCTURE_TYPE_SAMPLER_CREATE_INFO;
        sampler.magFilter = VK_FILTER_NEAREST;
        sampler.minFilter = VK_FILTER_NEAREST;
        sampler.mipmapMode = VK_SAMPLER_MIPMAP_MODE_NEAREST;
        sampler.addressModeU = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;
        sampler.addressModeV = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;
        sampler.addressModeW = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;
        r = d->vkCreateSampler(device, &sampler, NULL, &impl->app_sampler);
        if (r != VK_SUCCESS) return r;
    }
    {
        VkBufferCreateInfo buffer_info;
        VkMemoryRequirements requirements;
        VkMemoryAllocateInfo allocation;
        uint32_t type = 0;
        hbx_memset(&buffer_info, 0, sizeof buffer_info);
        buffer_info.sType = VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO;
        buffer_info.size = 512u * 512u * 4u;
        buffer_info.usage = VK_BUFFER_USAGE_TRANSFER_SRC_BIT;
        r = d->vkCreateBuffer(device, &buffer_info, NULL, &impl->app_staging);
        if (r != VK_SUCCESS) return r;
        hbx_memset(&requirements, 0, sizeof requirements);
        d->vkGetBufferMemoryRequirements(device, impl->app_staging, &requirements);
        r = device_memory_type(impl, VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT |
                                       VK_MEMORY_PROPERTY_HOST_COHERENT_BIT,
                               requirements.memoryTypeBits, &type);
        if (r != VK_SUCCESS) return r;
        hbx_memset(&allocation, 0, sizeof allocation);
        allocation.sType = VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO;
        allocation.allocationSize = requirements.size;
        allocation.memoryTypeIndex = type;
        r = d->vkAllocateMemory(device, &allocation, NULL, &impl->app_staging_memory);
        if (r != VK_SUCCESS) return r;
        r = d->vkBindBufferMemory(device, impl->app_staging, impl->app_staging_memory, 0);
        if (r != VK_SUCCESS) return r;
        r = d->vkMapMemory(device, impl->app_staging_memory, 0, VK_WHOLE_SIZE, 0,
                           (void **)&impl->app_staging_mapped);
        if (r != VK_SUCCESS || !impl->app_staging_mapped) return VK_ERROR_MEMORY_MAP_FAILED;
        hbx_memset(impl->app_staging_mapped, 0, 512u * 512u * 4u);
    }
    /* Undefined contents, but it must start in the sampled layout. */
    impl->app_layout = VK_IMAGE_LAYOUT_UNDEFINED;
    r = upload_image(impl, impl->app_image, VK_FORMAT_R8G8B8A8_UNORM, &impl->app_layout,
                     512, 512, 1, 1, 512u * 512u * 4u, impl->app_staging_mapped);
    if (r != VK_SUCCESS) return r;

    /* Vertex buffer: host-visible and mapped for direct CPU writes. */
    impl->vertex_capacity = HBX_UI_MAX_VERTICES;
    hbx_memset(&buffer_info, 0, sizeof buffer_info);
    buffer_info.sType = VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO;
    buffer_info.size = (VkDeviceSize)impl->vertex_capacity * HBX_UI_VERTEX_BYTES;
    buffer_info.usage = VK_BUFFER_USAGE_VERTEX_BUFFER_BIT;
    buffer_info.sharingMode = VK_SHARING_MODE_EXCLUSIVE;
    r = d->vkCreateBuffer(device, &buffer_info, NULL, &impl->vertex_buffer);
    if (r != VK_SUCCESS) return r;
    hbx_memset(&requirements, 0, sizeof requirements);
    d->vkGetBufferMemoryRequirements(device, impl->vertex_buffer, &requirements);
    r = device_memory_type(impl, VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT |
                                   VK_MEMORY_PROPERTY_HOST_COHERENT_BIT,
                           requirements.memoryTypeBits, &type);
    if (r != VK_SUCCESS) return r;
    hbx_memset(&allocation, 0, sizeof allocation);
    allocation.sType = VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO;
    allocation.allocationSize = requirements.size;
    allocation.memoryTypeIndex = type;
    r = d->vkAllocateMemory(device, &allocation, NULL, &impl->vertex_memory);
    if (r != VK_SUCCESS) return r;
    r = d->vkBindBufferMemory(device, impl->vertex_buffer, impl->vertex_memory, 0);
    if (r != VK_SUCCESS) return r;
    r = d->vkMapMemory(device, impl->vertex_memory, 0, VK_WHOLE_SIZE, 0,
                       (void **)&impl->vertex_mapped);
    if (r != VK_SUCCESS) return r;
    if (!impl->vertex_mapped) return VK_ERROR_MEMORY_MAP_FAILED;

    r = create_pipeline(impl);
    if (r != VK_SUCCESS) return r;

    impl->ready = 1;
    return VK_SUCCESS;
}

/* ------------------------------------------------------------------ */
/* Geometry                                                           */
/* ------------------------------------------------------------------ */

void hbx_ui_engine_begin(struct hbx_ui_impl *impl, uint32_t background) {
    if (!impl || !impl->ready) return;
    impl->vertex_count = 0;
    impl->background = background;
    impl->overflow = 0;
}

/* Reserve room for a whole primitive so a full buffer never truncates a
 * triangle into a stray vertex. */
static int reserve_vertices(struct hbx_ui_impl *impl, uint32_t count) {
    if (!impl || impl->vertex_count + count > impl->vertex_capacity) {
        if (impl) impl->overflow = 1;
        return 0;
    }
    return 1;
}

static struct hbx_ui_vertex *push_vertex(struct hbx_ui_impl *impl) {
    if (!impl || impl->vertex_count >= impl->vertex_capacity) {
        if (impl) impl->overflow = 1;
        return NULL;
    }
    return &impl->vertex_mapped[impl->vertex_count++];
}

void hbx_ui_engine_emit(struct hbx_ui_impl *impl, const struct hbx_ui_vertex *vertices,
                 uint32_t count) {
    uint32_t i;
    if (!impl || !vertices) return;
    for (i = 0; i < count; i++) {
        struct hbx_ui_vertex *vertex = push_vertex(impl);
        if (!vertex) return;
        *vertex = vertices[i];
    }
}

static void vertex_at(struct hbx_ui_impl *impl, float x, float y, float u, float v,
                      uint32_t color, uint32_t tex) {
    struct hbx_ui_vertex *vertex = push_vertex(impl);
    if (!vertex) return;
    vertex->x = x;
    vertex->y = y;
    vertex->u = u;
    vertex->v = v;
    vertex->color = color;
    vertex->tex = tex;
}

static void triangle(struct hbx_ui_impl *impl, float x0, float y0, float x1, float y1,
                     float x2, float y2, uint32_t c0, uint32_t c1, uint32_t c2) {
    if (!reserve_vertices(impl, 3)) return;
    vertex_at(impl, x0, y0, 0.0f, 0.0f, c0, HBX_TEX_SOLID);
    vertex_at(impl, x1, y1, 0.0f, 0.0f, c1, HBX_TEX_SOLID);
    vertex_at(impl, x2, y2, 0.0f, 0.0f, c2, HBX_TEX_SOLID);
}

static void quad(struct hbx_ui_impl *impl, float x, float y, float w, float h,
                 uint32_t color) {
    triangle(impl, x, y, x + w, y, x + w, y + h, color, color, color);
    triangle(impl, x, y, x + w, y + h, x, y + h, color, color, color);
}

static void quad_uv(struct hbx_ui_impl *impl, float x, float y, float w, float h,
                    float u0, float v0, float u1, float v1, uint32_t color, uint32_t tex) {
    if (!reserve_vertices(impl, 6)) return;
    vertex_at(impl, x, y, u0, v0, color, tex);
    vertex_at(impl, x + w, y, u1, v0, color, tex);
    vertex_at(impl, x + w, y + h, u1, v1, color, tex);
    vertex_at(impl, x, y, u0, v0, color, tex);
    vertex_at(impl, x + w, y + h, u1, v1, color, tex);
    vertex_at(impl, x, y + h, u0, v1, color, tex);
}

/* Write `count` perimeter points of a rounded rectangle, starting at the
 * top-left corner arc.  Both the outer edge and the inset edge of a stroke use
 * the same parameterisation so the ring connects cleanly. */
static uint32_t rounded_perimeter(float x, float y, float w, float h, float radius,
                                  float *out, uint32_t segments) {
    float cx[4], cy[4], start[4];
    uint32_t n = 0;
    uint32_t corner, step;
    if (radius < 0.0f) radius = 0.0f;
    if (radius > w * 0.5f) radius = w * 0.5f;
    if (radius > h * 0.5f) radius = h * 0.5f;
    cx[0] = x + radius;         cy[0] = y + radius;         start[0] = HBX_PI;
    cx[1] = x + w - radius;     cy[1] = y + radius;         start[1] = -HBX_PI * 0.5f;
    cx[2] = x + w - radius;     cy[2] = y + h - radius;     start[2] = 0.0f;
    cx[3] = x + radius;         cy[3] = y + h - radius;     start[3] = HBX_PI * 0.5f;
    for (corner = 0; corner < 4u; corner++) {
        for (step = 0; step <= segments; step++) {
            float angle = start[corner] + HBX_PI * 0.5f * (float)step / (float)segments;
            out[n * 2] = cx[corner] + radius * hbx_cosf(angle);
            out[n * 2 + 1] = cy[corner] + radius * hbx_sinf(angle);
            n++;
        }
    }
    return n;
}

#define HBX_MAX_PERIMETER 128u

static void fill_rounded(struct hbx_ui_impl *impl, float x, float y, float w, float h,
                         float radius, uint32_t color) {
    float points[HBX_MAX_PERIMETER * 2];
    float cx, cy;
    uint32_t segments, count, i;
    if (w <= 0.0f || h <= 0.0f) return;
    if (radius < 0.5f) { quad(impl, x, y, w, h, color); return; }
    segments = (uint32_t)(radius / 3.0f) + 3u;
    if (segments > 12u) segments = 12u;
    count = rounded_perimeter(x, y, w, h, radius, points, segments);
    if (count + 2u > HBX_MAX_PERIMETER) return;
    cx = x + w * 0.5f;
    cy = y + h * 0.5f;
    for (i = 0; i < count; i++) {
        uint32_t next = (i + 1u) % count;
        triangle(impl, cx, cy, points[i * 2], points[i * 2 + 1],
                 points[next * 2], points[next * 2 + 1], color, color, color);
    }
}

static void stroke_rounded(struct hbx_ui_impl *impl, float x, float y, float w, float h,
                           float radius, float thickness, uint32_t color) {
    float outer[HBX_MAX_PERIMETER * 2];
    float inner[HBX_MAX_PERIMETER * 2];
    float ix = x + thickness, iy = y + thickness;
    float iw = w - thickness * 2.0f, ih = h - thickness * 2.0f;
    float ir = radius - thickness;
    uint32_t segments, count, i;
    if (w <= 0.0f || h <= 0.0f || thickness <= 0.0f) return;
    if (iw <= 0.0f || ih <= 0.0f) return;
    if (ir < 0.0f) ir = 0.0f;
    segments = (uint32_t)(radius / 3.0f) + 3u;
    if (segments > 12u) segments = 12u;
    count = rounded_perimeter(x, y, w, h, radius, outer, segments);
    if (count != rounded_perimeter(ix, iy, iw, ih, ir, inner, segments)) return;
    if (count + 1u > HBX_MAX_PERIMETER) return;
    for (i = 0; i < count; i++) {
        uint32_t next = (i + 1u) % count;
        if (!reserve_vertices(impl, 6)) return;
        vertex_at(impl, outer[i * 2], outer[i * 2 + 1], 0, 0, color, HBX_TEX_SOLID);
        vertex_at(impl, outer[next * 2], outer[next * 2 + 1], 0, 0, color, HBX_TEX_SOLID);
        vertex_at(impl, inner[next * 2], inner[next * 2 + 1], 0, 0, color, HBX_TEX_SOLID);
        vertex_at(impl, outer[i * 2], outer[i * 2 + 1], 0, 0, color, HBX_TEX_SOLID);
        vertex_at(impl, inner[next * 2], inner[next * 2 + 1], 0, 0, color, HBX_TEX_SOLID);
        vertex_at(impl, inner[i * 2], inner[i * 2 + 1], 0, 0, color, HBX_TEX_SOLID);
    }
}

static void line_segment(struct hbx_ui_impl *impl, float x0, float y0, float x1, float y1,
                         float width, uint32_t color, uint32_t flags) {
    float dx = x1 - x0, dy = y1 - y0;
    float length = hbx_sqrtf(dx * dx + dy * dy);
    float nx, ny;
    float half = width * 0.5f;
    uint32_t edge = color & 0x00ffffffu;   /* feather: zero alpha at the edge */
    if (length < 0.0001f || width <= 0.0f) return;
    nx = -dy / length * half;
    ny = dx / length * half;
    if (flags & HBX_LINE_SOFT) {
        float inner = half > 0.75f ? half - 0.75f : half * 0.5f;
        float nx2 = nx * inner / half, ny2 = ny * inner / half;
        if (!reserve_vertices(impl, 18)) return;
        /* Two feathered halves: transparent rim, solid core. */
        vertex_at(impl, x0 + nx, y0 + ny, 0, 0, edge, HBX_TEX_SOLID);
        vertex_at(impl, x1 + nx, y1 + ny, 0, 0, edge, HBX_TEX_SOLID);
        vertex_at(impl, x1 + nx2, y1 + ny2, 0, 0, color, HBX_TEX_SOLID);
        vertex_at(impl, x0 + nx, y0 + ny, 0, 0, edge, HBX_TEX_SOLID);
        vertex_at(impl, x1 + nx2, y1 + ny2, 0, 0, color, HBX_TEX_SOLID);
        vertex_at(impl, x0 + nx2, y0 + ny2, 0, 0, color, HBX_TEX_SOLID);

        vertex_at(impl, x0 + nx2, y0 + ny2, 0, 0, color, HBX_TEX_SOLID);
        vertex_at(impl, x1 + nx2, y1 + ny2, 0, 0, color, HBX_TEX_SOLID);
        vertex_at(impl, x1 - nx2, y1 - ny2, 0, 0, color, HBX_TEX_SOLID);
        vertex_at(impl, x0 + nx2, y0 + ny2, 0, 0, color, HBX_TEX_SOLID);
        vertex_at(impl, x1 - nx2, y1 - ny2, 0, 0, color, HBX_TEX_SOLID);
        vertex_at(impl, x0 - nx2, y0 - ny2, 0, 0, color, HBX_TEX_SOLID);

        vertex_at(impl, x0 - nx2, y0 - ny2, 0, 0, color, HBX_TEX_SOLID);
        vertex_at(impl, x1 - nx2, y1 - ny2, 0, 0, color, HBX_TEX_SOLID);
        vertex_at(impl, x1 - nx, y1 - ny, 0, 0, edge, HBX_TEX_SOLID);
        vertex_at(impl, x0 - nx2, y0 - ny2, 0, 0, color, HBX_TEX_SOLID);
        vertex_at(impl, x1 - nx, y1 - ny, 0, 0, edge, HBX_TEX_SOLID);
        vertex_at(impl, x0 - nx, y0 - ny, 0, 0, edge, HBX_TEX_SOLID);
    } else {
        if (!reserve_vertices(impl, 6)) return;
        vertex_at(impl, x0 + nx, y0 + ny, 0, 0, color, HBX_TEX_SOLID);
        vertex_at(impl, x1 + nx, y1 + ny, 0, 0, color, HBX_TEX_SOLID);
        vertex_at(impl, x1 - nx, y1 - ny, 0, 0, color, HBX_TEX_SOLID);
        vertex_at(impl, x0 + nx, y0 + ny, 0, 0, color, HBX_TEX_SOLID);
        vertex_at(impl, x1 - nx, y1 - ny, 0, 0, color, HBX_TEX_SOLID);
        vertex_at(impl, x0 - nx, y0 - ny, 0, 0, color, HBX_TEX_SOLID);
    }

    if ((flags & HBX_LINE_ROUND) && half >= 0.5f) {
        /* Half-disc caps without atan2:
         *   p(t) = c + r * (n cos(pi t) - d sin(pi t)),  t in [0, 1]
         * sweeps from +normal, around the back of the endpoint, to -normal. */
        const uint32_t steps = 8;
        float ux = dx / length, uy = dy / length;
        uint32_t cap;
        for (cap = 0; cap < 2u; cap++) {
            float cx = cap == 0 ? x0 : x1;
            float cy = cap == 0 ? y0 : y1;
            float sign = cap == 0 ? 1.0f : -1.0f;
            uint32_t step;
            if (!reserve_vertices(impl, steps)) return;
            for (step = 0; step < steps; step++) {
                float t0 = (float)step / (float)steps;
                float t1 = (float)(step + 1u) / (float)steps;
                float c0 = hbx_cosf(HBX_PI * t0), s0 = hbx_sinf(HBX_PI * t0);
                float c1 = hbx_cosf(HBX_PI * t1), s1 = hbx_sinf(HBX_PI * t1);
                vertex_at(impl, cx, cy, 0, 0, color, HBX_TEX_SOLID);
                vertex_at(impl, cx + sign * (nx * c0 - ux * half * s0),
                          cy + sign * (ny * c0 - uy * half * s0), 0, 0, color, HBX_TEX_SOLID);
                vertex_at(impl, cx + sign * (nx * c1 - ux * half * s1),
                          cy + sign * (ny * c1 - uy * half * s1), 0, 0, color, HBX_TEX_SOLID);
            }
        }
    }
}

static void fill_circle(struct hbx_ui_impl *impl, float cx, float cy, float radius,
                        uint32_t color) {
    uint32_t segments = 36, i;
    for (i = 0; i < segments; i++) {
        float a0 = HBX_TAU * (float)i / (float)segments;
        float a1 = HBX_TAU * (float)(i + 1u) / (float)segments;
        triangle(impl, cx, cy, cx + radius * hbx_cosf(a0), cy + radius * hbx_sinf(a0),
                 cx + radius * hbx_cosf(a1), cy + radius * hbx_sinf(a1),
                 color, color, color);
    }
}

static void ring(struct hbx_ui_impl *impl, float cx, float cy, float radius,
                 float thickness, uint32_t color) {
    uint32_t segments = 48, i;
    float inner = radius - thickness;
    if (inner < 0.0f) inner = 0.0f;
    for (i = 0; i < segments; i++) {
        float a0 = HBX_TAU * (float)i / (float)segments;
        float a1 = HBX_TAU * (float)(i + 1u) / (float)segments;
        float o0x, o0y;
        if (!reserve_vertices(impl, 6)) return;
        o0x = cx + radius * hbx_cosf(a0); o0y = cy + radius * hbx_sinf(a0);
        float o1x = cx + radius * hbx_cosf(a1), o1y = cy + radius * hbx_sinf(a1);
        float i0x = cx + inner * hbx_cosf(a0), i0y = cy + inner * hbx_sinf(a0);
        float i1x = cx + inner * hbx_cosf(a1), i1y = cy + inner * hbx_sinf(a1);
        vertex_at(impl, o0x, o0y, 0, 0, color, HBX_TEX_SOLID);
        vertex_at(impl, o1x, o1y, 0, 0, color, HBX_TEX_SOLID);
        vertex_at(impl, i1x, i1y, 0, 0, color, HBX_TEX_SOLID);
        vertex_at(impl, o0x, o0y, 0, 0, color, HBX_TEX_SOLID);
        vertex_at(impl, i1x, i1y, 0, 0, color, HBX_TEX_SOLID);
        vertex_at(impl, i0x, i0y, 0, 0, color, HBX_TEX_SOLID);
    }
}

/* ------------------------------------------------------------------ */
/* Text                                                               */
/* ------------------------------------------------------------------ */

static const struct hbx_glyph *glyph_for(uint32_t font, unsigned char code) {
    if (font >= HBX_FACE_COUNT) font = HBX_FACE_COUNT - 1u;
    if (code < HBX_GLYPH_FIRST || code > HBX_GLYPH_LAST) return NULL;
    return &hbx_font_glyphs[font][code - HBX_GLYPH_FIRST];
}

static float text_draw(struct hbx_ui_impl *impl, float x, float y, uint32_t font,
                       const char *text, uint32_t color) {
    float pen;
    if (!text) return 0.0f;
    pen = hbx_floorf(x);
    while (*text) {
        const struct hbx_glyph *glyph = glyph_for(font, (unsigned char)*text++);
        if (glyph) {
            if (glyph->w && glyph->h) {
                float u0 = (float)glyph->x / (float)HBX_ATLAS_SIZE;
                float v0 = (float)glyph->y / (float)HBX_ATLAS_SIZE;
                float u1 = (float)(glyph->x + glyph->w) / (float)HBX_ATLAS_SIZE;
                float v1 = (float)(glyph->y + glyph->h) / (float)HBX_ATLAS_SIZE;
                quad_uv(impl, hbx_floorf(pen + glyph->ox), hbx_floorf(y + glyph->oy),
                        (float)glyph->w, (float)glyph->h, u0, v0, u1, v1,
                        color, HBX_TEX_GLYPH);
            }
            pen += (float)glyph->advance;
        } else {
            pen += 8.0f;
        }
    }
    return pen - hbx_floorf(x);
}

static float text_measure(uint32_t font, const char *text) {
    float pen = 0.0f;
    if (!text) return 0.0f;
    while (*text) {
        const struct hbx_glyph *glyph = glyph_for(font, (unsigned char)*text++);
        pen += glyph ? (float)glyph->advance : 8.0f;
    }
    return pen;
}

static void icon_draw(struct hbx_ui_impl *impl, float x, float y, float size,
                      uint32_t layer, uint32_t tint) {
    if (layer == HBX_ICON_NONE || layer >= impl->icon_layers) return;
    quad_uv(impl, x, y, size, size, 0.0f, 0.0f, 1.0f, 1.0f, tint,
            HBX_TEX_ICON | (layer << HBX_TEX_LAYER_SHIFT));
}

/* ------------------------------------------------------------------ */
/* Frame recording and presentation                                   */
/* ------------------------------------------------------------------ */

static VkResult record_frame(struct hbx_ui_impl *impl, VkCommandBuffer command,
                             VkImage image, VkImageView view, VkImageLayout final_layout) {
    VkCommandBufferBeginInfo begin;
    VkRenderingAttachmentInfo attachment;
    VkRenderingInfo rendering;
    VkViewport viewport;
    VkRect2D scissor;
    VkBuffer buffer = impl->vertex_buffer;
    VkDeviceSize offset = 0;
    float screen[2];
    float r = (float)(impl->background & 0xffu) / 255.0f;
    float g = (float)((impl->background >> 8) & 0xffu) / 255.0f;
    float b = (float)((impl->background >> 16) & 0xffu) / 255.0f;
    float a = (float)((impl->background >> 24) & 0xffu) / 255.0f;
    VkResult result;

    hbx_memset(&begin, 0, sizeof begin);
    begin.sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO;
    begin.flags = VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;
    result = impl->d->vkBeginCommandBuffer(command, &begin);
    if (result != VK_SUCCESS) return result;

    /* The acquire semaphore is waited on at COLOR_ATTACHMENT_OUTPUT, so the
     * first use of the image is synchronised in that stage too; TOP_OF_PIPE
     * would let the transition run before the acquire completed. */
    transition_image(impl, command, image, VK_IMAGE_LAYOUT_UNDEFINED,
                     VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL, 0,
                     VK_ACCESS_COLOR_ATTACHMENT_WRITE_BIT,
                     VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT,
                     VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT);

    if (impl->app_dirty) {
        VkBufferImageCopy copy;
        hbx_memset(&copy, 0, sizeof copy);
        copy.bufferRowLength = 512;
        copy.imageSubresource.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;
        copy.imageSubresource.layerCount = 1;
        copy.imageExtent.width = impl->app_width;
        copy.imageExtent.height = impl->app_height;
        copy.imageExtent.depth = 1;
        transition_image(impl, command, impl->app_image,
                         VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL,
                         VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL,
                         VK_ACCESS_SHADER_READ_BIT, VK_ACCESS_TRANSFER_WRITE_BIT,
                         VK_PIPELINE_STAGE_FRAGMENT_SHADER_BIT,
                         VK_PIPELINE_STAGE_TRANSFER_BIT);
        impl->d->vkCmdCopyBufferToImage(command, impl->app_staging, impl->app_image,
                                        VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL, 1, &copy);
        transition_image(impl, command, impl->app_image,
                         VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL,
                         VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL,
                         VK_ACCESS_TRANSFER_WRITE_BIT, VK_ACCESS_SHADER_READ_BIT,
                         VK_PIPELINE_STAGE_TRANSFER_BIT,
                         VK_PIPELINE_STAGE_FRAGMENT_SHADER_BIT);
        impl->app_layout = VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL;
        impl->app_dirty = 0;
    }

    hbx_memset(&attachment, 0, sizeof attachment);
    attachment.sType = VK_STRUCTURE_TYPE_RENDERING_ATTACHMENT_INFO;
    attachment.imageView = view;
    attachment.imageLayout = VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL;
    attachment.loadOp = VK_ATTACHMENT_LOAD_OP_CLEAR;
    attachment.storeOp = VK_ATTACHMENT_STORE_OP_STORE;
    attachment.clearValue.color.float32[0] = r;
    attachment.clearValue.color.float32[1] = g;
    attachment.clearValue.color.float32[2] = b;
    attachment.clearValue.color.float32[3] = a;

    hbx_memset(&rendering, 0, sizeof rendering);
    rendering.sType = VK_STRUCTURE_TYPE_RENDERING_INFO;
    rendering.renderArea.extent.width = impl->width;
    rendering.renderArea.extent.height = impl->height;
    rendering.layerCount = 1;
    rendering.colorAttachmentCount = 1;
    rendering.pColorAttachments = &attachment;
    impl->d->vkCmdBeginRendering(command, &rendering);

    hbx_memset(&viewport, 0, sizeof viewport);
    viewport.width = (float)impl->width;
    viewport.height = (float)impl->height;
    viewport.maxDepth = 1.0f;
    hbx_memset(&scissor, 0, sizeof scissor);
    scissor.extent.width = impl->width;
    scissor.extent.height = impl->height;
    impl->d->vkCmdBindPipeline(command, VK_PIPELINE_BIND_POINT_GRAPHICS, impl->pipeline);
    impl->d->vkCmdBindDescriptorSets(command, VK_PIPELINE_BIND_POINT_GRAPHICS,
                                     impl->pipeline_layout, 0, 1,
                                     &impl->descriptor_set, 0, NULL);
    impl->d->vkCmdBindVertexBuffers(command, 0, 1, &buffer, &offset);
    screen[0] = (float)impl->width;
    screen[1] = (float)impl->height;
    impl->d->vkCmdPushConstants(command, impl->pipeline_layout, VK_SHADER_STAGE_VERTEX_BIT,
                                0, sizeof screen, screen);
    if (impl->vertex_count) {
        impl->d->vkCmdDraw(command, impl->vertex_count, 1, 0, 0);
    }
    impl->d->vkCmdEndRendering(command);

    transition_image(impl, command, image, VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL,
                     final_layout, VK_ACCESS_COLOR_ATTACHMENT_WRITE_BIT,
                     final_layout == VK_IMAGE_LAYOUT_PRESENT_SRC_KHR
                         ? 0 : VK_ACCESS_TRANSFER_READ_BIT,
                     VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT,
                     final_layout == VK_IMAGE_LAYOUT_PRESENT_SRC_KHR
                         ? VK_PIPELINE_STAGE_BOTTOM_OF_PIPE_BIT
                         : VK_PIPELINE_STAGE_TRANSFER_BIT);
    return impl->d->vkEndCommandBuffer(command);
}

VkResult hbx_ui_attach_swapchain(struct hbx_ui_impl *impl, VkSwapchainKHR swapchain,
                                 VkSurfaceKHR surface, uint32_t image_count,
                                 const VkImage *images, const VkImageView *views,
                                 VkSemaphore acquire, VkSemaphore render) {
    VkSemaphoreCreateInfo semaphore_info;
    uint32_t i;
    VkResult r;
    if (!impl || !impl->ready) return VK_ERROR_INITIALIZATION_FAILED;
    if (image_count == 0 || image_count > HBX_MAX_IMAGES) return VK_ERROR_INITIALIZATION_FAILED;
    impl->swapchain = swapchain;
    impl->surface = surface;
    impl->image_count = image_count;
    for (i = 0; i < image_count; i++) {
        impl->images[i] = images[i];
        impl->views[i] = views[i];
    }
    impl->acquire_semaphore = acquire;
    (void)render;
    /* One render-finished semaphore per image: presentation may still own the
     * previous one, and vkQueueWaitIdle does not prove otherwise. */
    hbx_memset(&semaphore_info, 0, sizeof semaphore_info);
    semaphore_info.sType = VK_STRUCTURE_TYPE_SEMAPHORE_CREATE_INFO;
    for (i = 0; i < image_count; i++) {
        impl->render_semaphores[i] = VK_NULL_HANDLE;
        r = impl->d->vkCreateSemaphore(impl->device, &semaphore_info, NULL,
                                       &impl->render_semaphores[i]);
        if (r != VK_SUCCESS) return r;
    }
    return VK_SUCCESS;
}

VkResult hbx_ui_set_icons(struct hbx_ui_impl *impl, const void *pixels, uint32_t layers) {
    if (!impl || !impl->ready || !pixels) return VK_ERROR_INITIALIZATION_FAILED;
    if (layers == 0 || layers > impl->icon_layers) return VK_ERROR_INITIALIZATION_FAILED;
    /* Only the provided layers are copied; the rest keep their contents
     * because the transition starts from the image's real layout. */
    return upload_image(impl, impl->icon_image, VK_FORMAT_R8G8B8A8_UNORM,
                        &impl->icon_layout, HBX_ICON_SIZE, HBX_ICON_SIZE,
                        impl->icon_layers, layers,
                        HBX_ICON_SIZE * HBX_ICON_SIZE * 4u, pixels);
}

static VkResult present(struct hbx_ui_impl *impl) {
    uint32_t index = 0;
    VkResult r;
    VkSubmitInfo submit;
    VkPresentInfoKHR present_info;
    VkPipelineStageFlags wait_stage = VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT;
    VkSemaphore render_semaphore;
    VkSwapchainKHR swapchain = impl->swapchain;

    if (!impl->ready || !impl->swapchain) return VK_ERROR_INITIALIZATION_FAILED;
    /* The proven display path on this console acquires with the *2KHR* form
     * (VkAcquireNextImageInfoKHR); keep KHR as a fallback for other builds. */
    if (impl->d->vkAcquireNextImage2KHR) {
        VkAcquireNextImageInfoKHR info;
        hbx_memset(&info, 0, sizeof info);
        info.sType = VK_STRUCTURE_TYPE_ACQUIRE_NEXT_IMAGE_INFO_KHR;
        info.swapchain = swapchain;
        /* Bounded: the vi compositor can hold an image for a while; an
         * infinite wait would hang the app's loop forever (seen on hardware). */
        info.timeout = 100000000ull;
        info.semaphore = impl->acquire_semaphore;
        info.fence = VK_NULL_HANDLE;
        info.deviceMask = 1;
        r = impl->d->vkAcquireNextImage2KHR(impl->device, &info, &index);
    } else {
        r = impl->d->vkAcquireNextImageKHR(impl->device, swapchain, 100000000ull,
                                           impl->acquire_semaphore, VK_NULL_HANDLE, &index);
    }
    if (r == VK_ERROR_OUT_OF_DATE_KHR) {
        /* A stale swapchain ends the frame, not the session.  The vi surface is
           fixed-size on console; the workstation preview can resize. */
        impl->out_of_date++;
        return VK_SUCCESS;
    }
    if (r != VK_SUCCESS && r != VK_SUBOPTIMAL_KHR) {
        impl->last_error = (uint32_t)r;
        return r;
    }
    if (index >= impl->image_count) {
        impl->last_error = (uint32_t)VK_ERROR_INITIALIZATION_FAILED;
        return VK_ERROR_INITIALIZATION_FAILED;
    }
    render_semaphore = impl->render_semaphores[index];
    r = record_frame(impl, impl->commands[index], impl->images[index],
                     impl->views[index], VK_IMAGE_LAYOUT_PRESENT_SRC_KHR);
    if (r != VK_SUCCESS) {
        impl->last_error = (uint32_t)r;
        return r;
    }

    hbx_memset(&submit, 0, sizeof submit);
    submit.sType = VK_STRUCTURE_TYPE_SUBMIT_INFO;
    submit.waitSemaphoreCount = 1;
    submit.pWaitSemaphores = &impl->acquire_semaphore;
    submit.pWaitDstStageMask = &wait_stage;
    submit.commandBufferCount = 1;
    submit.pCommandBuffers = &impl->commands[index];
    submit.signalSemaphoreCount = 1;
    submit.pSignalSemaphores = &render_semaphore;
    r = impl->d->vkQueueSubmit(impl->queue, 1, &submit, VK_NULL_HANDLE);
    if (r != VK_SUCCESS) {
        impl->last_error = (uint32_t)r;
        return r;
    }
    hbx_memset(&present_info, 0, sizeof present_info);
    present_info.sType = VK_STRUCTURE_TYPE_PRESENT_INFO_KHR;
    present_info.waitSemaphoreCount = 1;
    present_info.pWaitSemaphores = &render_semaphore;
    present_info.swapchainCount = 1;
    present_info.pSwapchains = &swapchain;
    present_info.pImageIndices = &index;
    {
        VkResult present_result = impl->d->vkQueuePresentKHR(impl->queue, &present_info);
        VkResult idle_result = impl->d->vkQueueWaitIdle(impl->queue);
        if (idle_result != VK_SUCCESS) {
            impl->last_error = (uint32_t)idle_result;
            return idle_result;
        }
        if (present_result == VK_ERROR_OUT_OF_DATE_KHR) {
            impl->out_of_date++;
            impl->last_error = (uint32_t)present_result;
            return present_result;
        }
        if (present_result != VK_SUCCESS && present_result != VK_SUBOPTIMAL_KHR) {
            impl->last_error = (uint32_t)present_result;
            return present_result;
        }
    }
    impl->frame++;
    return VK_SUCCESS;
}

VkResult hbx_ui_render_offscreen(struct hbx_ui_impl *impl, VkImage image,
                                 VkImageView view, VkFormat format) {
    VkSubmitInfo submit;
    VkResult r;
    if (!impl || !impl->ready) return VK_ERROR_INITIALIZATION_FAILED;
    /* The pipeline was created for impl->format; a different attachment format
     * would be an invalid dynamic-rendering draw. */
    if (format != impl->format) return VK_ERROR_FORMAT_NOT_SUPPORTED;
    r = record_frame(impl, impl->commands[0], image, view,
                     VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL);
    if (r != VK_SUCCESS) return r;
    hbx_memset(&submit, 0, sizeof submit);
    submit.sType = VK_STRUCTURE_TYPE_SUBMIT_INFO;
    submit.commandBufferCount = 1;
    submit.pCommandBuffers = &impl->commands[0];
    r = impl->d->vkQueueSubmit(impl->queue, 1, &submit, VK_NULL_HANDLE);
    if (r != VK_SUCCESS) return r;
    impl->frame++;
    return impl->d->vkQueueWaitIdle(impl->queue);
}

/* ------------------------------------------------------------------ */
/* Ops table                                                          */
/* ------------------------------------------------------------------ */

static void op_begin(void *self, uint32_t background) {
    hbx_ui_engine_begin((struct hbx_ui_impl *)self, background);
}
static void op_rect(void *self, float x, float y, float w, float h, float radius,
                    uint32_t color) {
    fill_rounded((struct hbx_ui_impl *)self, x, y, w, h, radius, color);
}
static void op_stroke(void *self, float x, float y, float w, float h, float radius,
                      float thickness, uint32_t color) {
    stroke_rounded((struct hbx_ui_impl *)self, x, y, w, h, radius, thickness, color);
}
static float op_text(void *self, float x, float y, uint32_t font, const char *text,
                     uint32_t color) {
    return text_draw((struct hbx_ui_impl *)self, x, y, font, text, color);
}
static float op_text_width(void *self, uint32_t font, const char *text) {
    (void)self;
    return text_measure(font, text);
}
static void op_line(void *self, float x0, float y0, float x1, float y1, float width,
                    uint32_t color, uint32_t flags) {
    line_segment((struct hbx_ui_impl *)self, x0, y0, x1, y1, width, color, flags);
}
static void op_circle(void *self, float cx, float cy, float radius, float thickness,
                      uint32_t color, uint32_t flags) {
    struct hbx_ui_impl *impl = (struct hbx_ui_impl *)self;
    if (thickness <= 0.0f) fill_circle(impl, cx, cy, radius, color);
    else ring(impl, cx, cy, radius, thickness, color);
    (void)flags;
}
static void op_icon(void *self, float x, float y, float size, uint32_t layer,
                    uint32_t tint) {
    icon_draw((struct hbx_ui_impl *)self, x, y, size, layer, tint);
}
static void op_image(void *self, float x, float y, float width, float height,
                     const void *pixels, uint32_t iw, uint32_t ih) {
    struct hbx_ui_impl *impl = (struct hbx_ui_impl *)self;
    uint32_t row;
    if (!impl || !impl->ready || !pixels || iw == 0 || ih == 0 ||
        iw > 512u || ih > 512u || !impl->app_staging_mapped)
        return;
    for (row = 0; row < ih; row++)
        hbx_memcpy(impl->app_staging_mapped + (size_t)row * 512u * 4u,
                   (const unsigned char *)pixels + (size_t)row * iw * 4u,
                   (size_t)iw * 4u);
    impl->app_width = iw;
    impl->app_height = ih;
    impl->app_dirty = 1;
    quad_uv(impl, x, y, width, height,
            0.0f, 0.0f, (float)iw / 512.0f, (float)ih / 512.0f,
            0xffffffffu, HBX_TEX_IMAGE);
}

static void op_vertices(void *self, const void *vertices, uint32_t count) {
    hbx_ui_engine_emit((struct hbx_ui_impl *)self, (const struct hbx_ui_vertex *)vertices, count);
}
static int op_present(void *self) {
    return present((struct hbx_ui_impl *)self) == VK_SUCCESS ? HBX_OK : HBX_ERR_GPU;
}
static uint32_t op_frame(void *self) { return ((struct hbx_ui_impl *)self)->frame; }
static uint64_t op_device(void *self) {
    return (uint64_t)(uintptr_t)((struct hbx_ui_impl *)self)->device;
}
static uint64_t op_queue(void *self) {
    return (uint64_t)(uintptr_t)((struct hbx_ui_impl *)self)->queue;
}

static const struct hbx_ui_ops hbx_ui_ops = {
    HBX_RENDER_ABI,
    (uint32_t)sizeof(struct hbx_ui_ops),
    op_begin,
    op_rect,
    op_stroke,
    op_text,
    op_text_width,
    op_line,
    op_circle,
    op_icon,
    op_image,
    op_vertices,
    op_present,
    op_frame,
    op_device,
    op_queue
};

void hbx_ui_publish(struct hbx_ui_impl *impl, struct hbx_render *out) {
    if (!impl || !out) return;
    out->abi = HBX_RENDER_ABI;
    out->size = (uint32_t)sizeof(struct hbx_render);
    out->self = impl;
    out->ops = &hbx_ui_ops;
}

/* ------------------------------------------------------------------ */
/* Engine entry points used by the launcher and the preview           */
/* ------------------------------------------------------------------ */

void hbx_ui_engine_triangle(struct hbx_ui_impl *impl, float x0, float y0, float x1,
                            float y1, float x2, float y2, uint32_t c0, uint32_t c1,
                            uint32_t c2) {
    triangle(impl, x0, y0, x1, y1, x2, y2, c0, c1, c2);
}

void hbx_ui_engine_quad_gradient(struct hbx_ui_impl *impl, float x0, float y0,
                                 float x1, float y1, uint32_t top_left,
                                 uint32_t top_right, uint32_t bottom_right,
                                 uint32_t bottom_left) {
    /* Two triangles; the diagonal splits the interpolation consistently. */
    vertex_at(impl, x0, y0, 0, 0, top_left, HBX_TEX_SOLID);
    vertex_at(impl, x1, y0, 0, 0, top_right, HBX_TEX_SOLID);
    vertex_at(impl, x1, y1, 0, 0, bottom_right, HBX_TEX_SOLID);
    vertex_at(impl, x0, y0, 0, 0, top_left, HBX_TEX_SOLID);
    vertex_at(impl, x1, y1, 0, 0, bottom_right, HBX_TEX_SOLID);
    vertex_at(impl, x0, y1, 0, 0, bottom_left, HBX_TEX_SOLID);
}

void hbx_ui_engine_band(struct hbx_ui_impl *impl, float x0, float x1, float top,
                        float bottom_left, float bottom_right, uint32_t top_left,
                        uint32_t top_right, uint32_t bottom_left_color,
                        uint32_t bottom_right_color) {
    if (!reserve_vertices(impl, 6)) return;
    vertex_at(impl, x0, top, 0, 0, top_left, HBX_TEX_SOLID);
    vertex_at(impl, x1, top, 0, 0, top_right, HBX_TEX_SOLID);
    vertex_at(impl, x1, bottom_right, 0, 0, bottom_right_color, HBX_TEX_SOLID);
    vertex_at(impl, x0, top, 0, 0, top_left, HBX_TEX_SOLID);
    vertex_at(impl, x1, bottom_right, 0, 0, bottom_right_color, HBX_TEX_SOLID);
    vertex_at(impl, x0, bottom_left, 0, 0, bottom_left_color, HBX_TEX_SOLID);
}

void hbx_ui_engine_rect(struct hbx_ui_impl *impl, float x, float y, float w, float h,
                        float radius, uint32_t color) {
    fill_rounded(impl, x, y, w, h, radius, color);
}

void hbx_ui_engine_stroke(struct hbx_ui_impl *impl, float x, float y, float w, float h,
                          float radius, float thickness, uint32_t color) {
    stroke_rounded(impl, x, y, w, h, radius, thickness, color);
}

float hbx_ui_engine_text(struct hbx_ui_impl *impl, float x, float y, uint32_t font,
                         const char *text, uint32_t color) {
    return text_draw(impl, x, y, font, text, color);
}

float hbx_ui_engine_text_width(uint32_t font, const char *text) {
    return text_measure(font, text);
}

void hbx_ui_engine_text_center(struct hbx_ui_impl *impl, float cx, float y, uint32_t font,
                               const char *text, uint32_t color) {
    float width = text_measure(font, text);
    text_draw(impl, hbx_floorf(cx - width * 0.5f), y, font, text, color);
}

void hbx_ui_engine_line(struct hbx_ui_impl *impl, float x0, float y0, float x1, float y1,
                        float width, uint32_t color, uint32_t flags) {
    line_segment(impl, x0, y0, x1, y1, width, color, flags);
}

void hbx_ui_engine_circle(struct hbx_ui_impl *impl, float cx, float cy, float radius,
                          float thickness, uint32_t color) {
    if (thickness <= 0.0f) fill_circle(impl, cx, cy, radius, color);
    else ring(impl, cx, cy, radius, thickness, color);
}

void hbx_ui_engine_icon(struct hbx_ui_impl *impl, float x, float y, float size,
                        uint32_t layer, uint32_t tint) {
    icon_draw(impl, x, y, size, layer, tint);
}

uint32_t hbx_ui_engine_vertex_count(const struct hbx_ui_impl *impl) {
    return impl ? impl->vertex_count : 0;
}

uint32_t hbx_ui_engine_overflow(const struct hbx_ui_impl *impl) {
    return impl ? impl->overflow : 0;
}
